    let cp = 0xfffd, n = 1;
    if (b < 0x80) { cp = b; }
    else if (b >= 0xc2 && b < 0xe0 && i + 1 < bytes.length && (bytes[i + 1] & 0xc0) === 0x80) { cp = ((b & 0x1f) << 6) | (bytes[i + 1] & 0x3f); n = 2; }
    else if (b >= 0xe0 && b < 0xf0 && i + 2 < bytes.length && (bytes[i + 1] & 0xc0) === 0x80 && (bytes[i + 2] & 0xc0) === 0x80) { cp = ((b & 0x0f) << 12) | ((bytes[i + 1] & 0x3f) << 6) | (bytes[i + 2] & 0x3f); n = 3; }
    else if (b >= 0xf0 && b < 0xf5 && i + 3 < bytes.length && (bytes[i + 1] & 0xc0) === 0x80 && (bytes[i + 2] & 0xc0) === 0x80 && (bytes[i + 3] & 0xc0) === 0x80) { cp = ((b & 0x07) << 18) | ((bytes[i + 1] & 0x3f) << 12) | ((bytes[i + 2] & 0x3f) << 6) | (bytes[i + 3] & 0x3f); n = 4; }
    parts.push(cp);
    i += n;
    if (parts.length >= 8192) { out += String.fromCodePoint.apply(null, parts); parts.length = 0; }
  }
  return out + String.fromCodePoint.apply(null, parts);
}

function utf8Encode(text) {
  if (typeof TextEncoder !== 'undefined') return new TextEncoder().encode(text);
  const out = [];
  for (const ch of text) {
    const cp = ch.codePointAt(0);
    if (cp < 0x80) out.push(cp);
    else if (cp < 0x800) out.push(0xc0 | (cp >> 6), 0x80 | (cp & 63));
    else if (cp < 0x10000) out.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 63), 0x80 | (cp & 63));
    else out.push(0xf0 | (cp >> 18), 0x80 | ((cp >> 12) & 63), 0x80 | ((cp >> 6) & 63), 0x80 | (cp & 63));
  }
  return new Uint8Array(out);
}

function toBytes(body) {
  if (body == null) return new Uint8Array(0);
  if (body instanceof Uint8Array) return body;
  if (typeof body === 'string') return utf8Encode(body);
  if (body.buffer instanceof ArrayBuffer) return new Uint8Array(body.buffer, body.byteOffset || 0, body.byteLength);
  return new Uint8Array(body);
}

function latin1(bytes, n) {
  const end = Math.min(bytes.length, n);
  let s = '';
  for (let i = 0; i < end; i += 8192) s += String.fromCharCode.apply(null, bytes.subarray(i, Math.min(end, i + 8192)));
  return s;
}

function lowerHeaders(headers) {
  const out = {};
  for (const [k, v] of Object.entries(headers || {})) out[String(k).toLowerCase()] = Array.isArray(v) ? v.join(', ') : String(v);
  return out;
}

/** Detecta el formato real del cuerpo, sin fiarse del Content-Type. */
function detectFormat(bytes, contentType) {
  if (!bytes.length) return 'empty';
  if (bytes[0] === 0x25 && bytes[1] === 0x50 && bytes[2] === 0x44 && bytes[3] === 0x46) return 'pdf';
  let head = latin1(bytes, 4096);
  if (head.charCodeAt(0) === 0xef && head.charCodeAt(1) === 0xbb && head.charCodeAt(2) === 0xbf) head = head.slice(3);
  head = head.replace(/^[\s\u0000]+/, '');
  const low = head.toLowerCase();
  if (low.startsWith('{') || low.startsWith('[')) {
    if (/"version"\s*:\s*"https:\/\/jsonfeed\.org/.test(low)) return 'jsonfeed';
    return 'json';
  }
  if (/<rss[\s>]/.test(low)) return 'rss';
  if (/<feed[\s>]/.test(low) && /xmlns="http:\/\/www\.w3\.org\/2005\/atom"/.test(low)) return 'atom';
  if (/<rdf:rdf[\s>]/.test(low)) return 'rdf';
  if (/<feed[\s>]/.test(low)) return 'atom';
  if (/<!doctype html|<html[\s>]|<head[\s>]|<body[\s>]/.test(low)) return 'html';
  if (low.startsWith('<?xml') || low.startsWith('<')) return /<html/.test(low) ? 'html' : 'xml';
  const ct = (contentType || '').toLowerCase();
  if (ct.includes('html')) return 'html';
  // Binario si hay muchos bytes de control en el inicio.
  let ctrl = 0;
  const n = Math.min(bytes.length, 2048);
  for (let i = 0; i < n; i++) { const b = bytes[i]; if (b < 9 || (b > 13 && b < 32)) ctrl++; }
  return ctrl > n * 0.05 ? 'binary' : 'text';
}

const FEED_FORMATS = ['rss', 'atom', 'rdf', 'jsonfeed'];

/** Cuenta entradas y la fecha más reciente de un feed (sin un lector XML
 * completo; el lector tolerante del pipeline es quien decide al final). */
function feedStats(text, format) {
  if (format === 'jsonfeed') {
    try {
      const j = JSON.parse(text);
      const items = Array.isArray(j.items) ? j.items : [];
      return { items: items.length, newest: newestDate(items.map((i) => i.date_published || i.date_modified)), title: String(j.title || '').slice(0, 120) };
    } catch (e) { return { items: 0, newest: null, title: '', parse_error: 'JSON Feed inválido' }; }
  }
  const items = (text.match(/<(item|entry)[\s>]/gi) || []).length;
  const dates = [];
  const re = /<(pubDate|updated|published|dc:date|lastBuildDate)[^>]*>([^<]{6,64})</gi;
  let m;
  while ((m = re.exec(text)) && dates.length < 500) dates.push(m[2].trim());
  const t = /<title[^>]*>(?:<!\[CDATA\[)?([^<\]]{1,200})/i.exec(text);
  return { items, newest: newestDate(dates), title: t ? t[1].trim().slice(0, 120) : '' };
}

function newestDate(values) {
  let best = null;
  for (const v of values) {
    if (!v) continue;
    const t = Date.parse(v);
    if (!Number.isNaN(t) && (best === null || t > best)) best = t;
  }
  return best === null ? null : new Date(best).toISOString();
}

function findBlock(scanLow, headers) {
  for (const sig of BLOCK_SIGNATURES) {
    for (const [h, v] of Object.entries(sig.header || {})) {
      if (h in headers && (!v || headers[h].toLowerCase().includes(v))) return sig.block;
    }
    for (const s of sig.body || []) if (scanLow.includes(s)) return sig.block;
  }
  return null;
}

/**
 * @param {object} r
 * @param {string} r.url
 * @param {string} [r.expect]  feed | html | pdf | json | text | any
 * @param {number|null} [r.status]
 * @param {object} [r.headers]
 * @param {Uint8Array|Buffer|string|null} [r.body]
 * @param {string|null} [r.error]  mensaje de error de red, si no hubo respuesta
 */
function classify(r) {
  const c = classifyRaw(r);
  c.reach = reachClass(c);
  return c;
}

function classifyRaw(r) {
  const headers = lowerHeaders(r.headers);
  const bytes = toBytes(r.body);
  const contentType = headers['content-type'] || '';
  const out = {
    ok: false, verdict: '', block: null, transient: false,
    status: r.status == null ? null : Number(r.status), bytes: bytes.length,
    content_type: contentType.slice(0, 120), detected: 'empty', items: null, newest: null, title: '', note: '',
  };
  const err = r.error ? String(r.error) : '';
  // Proxies de salida devuelven 502 con «upstream dial failed» cuando el nombre no resuelve.
  if (err || (out.status === 502 && /upstream dial failed/i.test(latin1(bytes, 200)))) {
    const msg = err || latin1(bytes, 200);
    const kind = ERROR_KINDS.find((k) => k.re.test(msg));
    out.verdict = kind ? kind.verdict : 'connection';
    out.transient = kind ? kind.transient : true;
    out.status = err ? null : out.status;
    out.note = msg.replace(/\s+/g, ' ').slice(0, 200);
    return out;
  }
  out.detected = detectFormat(bytes, contentType);
  const scan = latin1(bytes, SCAN_BYTES);
  // Las firmas con tildes se buscan en UTF-8 y en Latin-1.
  const scanLow = `${scan}\n${utf8Decode(bytes.subarray(0, SCAN_BYTES))}`.toLowerCase();
  const block = findBlock(scanLow, headers);
  const st = out.status;

  if (st === 429) { out.verdict = 'blocked'; out.block = 'rate-limit'; out.transient = true; return out; }
  if (st === 401 || st === 407) { out.verdict = 'blocked'; out.block = 'auth-required'; return out; }
  if (st === 403 || st === 451) { out.verdict = 'blocked'; out.block = block || (st === 451 ? 'legal' : 'http-403'); return out; }
  if (st === 404 || st === 410) { out.verdict = 'not_found'; return out; }
  if (st !== null && st >= 500) {
    out.verdict = block ? 'blocked' : 'server_error';
    out.block = block;
    out.transient = !block;
    return out;
  }
  if (st === 202 && (block || !bytes.length || out.detected === 'html')) {
    // 202 de anti-robots (ReliefWeb, AWS WAF): «aceptado», pero sin el contenido.
    out.verdict = 'blocked';
    out.block = block || 'bot-202';
    return out;
  }
  if (st !== null && (st < 200 || st >= 300)) {
    // 3xx que no se siguió, 1xx, etc.
    out.verdict = block ? 'blocked' : 'http_error';
    out.block = block;
    return out;
  }
  if (!bytes.length) { out.verdict = 'empty'; out.transient = true; return out; }

  // El registro dice «rss» para cualquier feed y «csv» para tablas de texto.
  const expect = ({ rss: 'feed', atom: 'feed', csv: 'text' })[(r.expect || 'any').toLowerCase()] || (r.expect || 'any').toLowerCase();
  const isFeed = FEED_FORMATS.includes(out.detected);
  // Una página de verificación responde 200 con HTML pequeño: es un bloqueo
  // solo si no es lo que se esperaba (un feed o PDF que menciona «captcha» no lo es).
  const unexpectedHtml = out.detected === 'html' && expect !== 'html' && expect !== 'any';
  if (block && (unexpectedHtml || (out.detected === 'html' && bytes.length < 40000))) {
    out.verdict = 'blocked';
    out.block = block;
    return out;
  }
  if (expect === 'feed') {
    if (!isFeed) {
      out.verdict = 'wrong_type';
      out.note = `se esperaba un feed y llegó ${out.detected}`;
      return out;
    }
    const st2 = feedStats(utf8Decode(bytes), out.detected);
    Object.assign(out, { items: st2.items, newest: st2.newest, title: st2.title });
    if (st2.parse_error) { out.verdict = 'parse_error'; out.note = st2.parse_error; return out; }
    if (!st2.items) { out.verdict = 'empty'; out.note = 'feed sin entradas'; return out; }
  } else if (expect === 'pdf') {
    if (out.detected !== 'pdf') { out.verdict = 'wrong_type'; out.note = `se esperaba PDF y llegó ${out.detected}`; return out; }
  } else if (expect === 'json') {
    if (out.detected !== 'json' && out.detected !== 'jsonfeed') { out.verdict = 'wrong_type'; out.note = `se esperaba JSON y llegó ${out.detected}`; return out; }
    try { JSON.parse(utf8Decode(bytes)); } catch (e) { out.verdict = 'parse_error'; out.note = 'JSON inválido'; return out; }
  } else if (expect === 'text') {
    if (out.detected === 'html' || out.detected === 'binary') { out.verdict = 'wrong_type'; out.note = `se esperaba texto y llegó ${out.detected}`; return out; }
  } else if (expect === 'html') {
    // Un bloqueo llega como HTML: si llegó otra cosa, no es un bloqueo y se
    // guarda igual (el registro puede equivocarse de tipo).
    if (out.detected !== 'html' && out.detected !== 'xml') out.note = `llegó ${out.detected}; el registro esperaba HTML`;
    else if (bytes.length < 500) { out.verdict = 'empty'; out.note = 'HTML casi vacío'; return out; }
  }
  if (out.detected === 'html' || out.detected === 'xml') {
    const t = /<title[^>]*>([^<]{1,200})/i.exec(scan);
    if (t && !out.title) out.title = t[1].trim().slice(0, 120);
  }
  out.ok = true;
  out.verdict = 'ok';
  return out;
}

/** Clase de alcance del registro (python/enso/reach.py: ok, empty, http-403,
 * http-4xx, http-5xx, timeout, connect, dns, tls, challenge), para que las
 * mediciones desde n8n se comparen con las de Actions y del Perú. */
function reachClass(c) {
  switch (c.verdict) {
    case 'ok': return 'ok';
    case 'timeout': return 'timeout';
    case 'connection': return 'connect';
    case 'dns': return 'dns';
    case 'tls': return 'tls';
    case 'not_found': case 'http_error': return 'http-4xx';
    case 'server_error': return 'http-5xx';
    case 'blocked':
      if (c.block === 'http-403') return 'http-403';
      if (c.block === 'rate-limit' || c.block === 'auth-required' || c.block === 'legal') return 'http-4xx';
      return 'challenge';
    default: return 'empty'; // vacío, tipo inesperado o ilegible: responde, pero sin contenido útil
  }
}

/** Extensión del archivo guardado según el formato detectado. */
function fileExtension(detected) {
  if (detected === 'pdf') return 'pdf';
  if (detected === 'json' || detected === 'jsonfeed') return 'json';
  if (['rss', 'atom', 'rdf', 'xml'].includes(detected)) return 'xml';
  if (detected === 'html') return 'html';
  return 'txt';
}

// URL de los PDF de los comunicados del ENFEN a partir de sus listados.
// Es el mismo criterio que python/enso/feeds/peru.py (parse_enfen_listing,
// parse_enfen_wp_posts) y que python/tools/peru_collector.py
// (enfen_documents): los dos comunicados oficiales más recientes y los dos
// números siguientes en la réplica de la DHN, que pueden existir antes de
// que el listado los muestre.

const DHN_BASE = 'https://www.dhn.mil.pe';
const ENFEN_BASE = 'https://enfen.imarpe.gob.pe';
const LISTING_RE = /href=["']([^"']*comunicado-(oficial|extraordinario)-enfen-n-?(\d{1,2})-(\d{4})[^"']*)["']/gi;
const DHN_RE = /href=["']([^"']*\/comunicado-(oficial|extraordinario)\/(\d{1,2})-(\d{4})\.pdf)["']/gi;
const NUMBER_RE = /COMUNICADO\s+OFICIAL\s+(?:DEL?\s+)?ENFEN\s+N\s*[°ºo.]*\s*(\d{1,2})\s*[-–]\s*(\d{4})/i;

function unescapeHtml(s) {
  return s.replace(/&#0?38;/g, '&').replace(/&amp;/g, '&');
}

/** Quita el parámetro «refresh» (token por visita) de los enlaces de descarga. */
function cleanWpdm(url) {
  return unescapeHtml(url).replace(/[&?]refresh=[^&]*/g, '');
}

function dhnPdf(n, y) {
  return `${DHN_BASE}/Archivos/oceanografia/enfen/comunicado-oficial/${String(n).padStart(2, '0')}-${y}.pdf`;
}

/** Comunicados en un listado HTML (portal del ENFEN o réplica de la DHN). */
function parseListing(html) {
  const seen = new Map();
  for (const rx of [LISTING_RE, DHN_RE]) {
    rx.lastIndex = 0;
    let m;
    while ((m = rx.exec(html))) {
      let url = unescapeHtml(m[1]);
      if (url.startsWith('/')) url = DHN_BASE + url;
      const key = `${m[2].toLowerCase()}|${m[4]}|${m[3].padStart(2, '0')}`;
      if (!seen.has(key)) seen.set(key, { kind: m[2].toLowerCase(), year: Number(m[4]), number: Number(m[3]), url });
    }
  }
  return [...seen.values()];
}

/** Comunicados en la respuesta JSON de WordPress del portal del ENFEN. */
function parseWpPosts(text) {
  let posts;
  try { posts = JSON.parse(text); } catch (e) { return []; }
  if (!Array.isArray(posts)) return [];
  const out = [];
  for (const p of posts) {
    const title = String((p.title || {}).rendered || '').replace(/<[^>]+>/g, ' ');
    const content = String((p.content || {}).rendered || '').replace(/<[^>]+>/g, ' ');
    const m = NUMBER_RE.exec(`${title} ${content}`) || /N\s*[°º]?\s*(\d{1,2})\s*[-–]\s*(\d{4})/.exec(title);
    if (!m || !(title + content.slice(0, 300)).toLowerCase().includes('comunicado')) continue;
    // La entrada trae el enlace de descarga (``?wpdmdl=`` o un .pdf) en su
    // contenido; si no, queda la página de la entrada.
    const html = String((p.content || {}).rendered || '');
    const dl = /href=["']([^"']*(?:[?&](?:amp;|#0?38;)?wpdmdl=\d+|\.pdf)[^"']*)["']/i.exec(html);
    out.push({ kind: 'oficial', year: Number(m[2]), number: Number(m[1]), url: dl ? dl[1] : (p.link || '') });
  }
  return out;
}

/**
 * @param {{url: string, text: string}[]} pages  listados descargados
 * @param {Date} [now]  para sondear el n.º 01 del año nuevo en enero
 * @returns {string[]} URL a descargar (sin repetir)
 */
function deriveEnfenTargets(pages, now = new Date()) {
  const items = [];
  for (const p of pages) {
    if (!p.text) continue;
    const t = p.text.trimStart();
    items.push(...(t.startsWith('[') ? parseWpPosts(t) : parseListing(p.text)));
  }
  const oficial = items.filter((i) => i.kind === 'oficial')
    .sort((a, b) => (b.year - a.year) || (b.number - a.number));
  if (!oficial.length) return [];
  const latest = [];
  for (const i of oficial) {
    if (!latest.some((x) => x.year === i.year && x.number === i.number)) latest.push(i);
    if (latest.length === 2) break;
  }
  const urls = [];
  for (const i of latest) {
    if (i.url) urls.push(cleanWpdm(i.url));
    urls.push(dhnPdf(i.number, i.year));
  }
  const { year, number } = latest[0];
  for (const k of [1, 2]) urls.push(dhnPdf(number + k, year));
  const thisYear = now.getUTCFullYear();
  if (year < thisYear) urls.push(dhnPdf(1, thisYear), dhnPdf(2, thisYear));
  return [...new Set(urls)];
}

// ---- nodo ----
// Segunda pasada: reintenta lo que falló por causas pasajeras (tiempo de
// espera, conexión cortada, 5xx, 429), sigue los enlaces que el registro
// indica (``follow``: p. ej. los PDF enlazados desde un listado) y agrega
// los PDF del ENFEN que se deducen de sus listados (mismo criterio que el
// pipeline). Si no hay nada que hacer, no devuelve nada y la rama de la
// segunda pasada no corre.
const items = $input.all();
const out = [];
const okUrls = new Set(items.filter((it) => it.json.cls.ok).map((it) => it.json.url));
const queued = new Set();
const add = (t) => {
  if (okUrls.has(t.url) || queued.has(t.url)) return;
  queued.add(t.url);
  out.push({ json: { pass: 2, ...t } });
};
for (const it of items) {
  const j = it.json;
  if (!j.cls.ok && j.cls.transient) add({ id: j.id, group: j.group, name: j.name, url: j.url, expect: j.expect });
}
const pages = [];
for (let i = 0; i < items.length; i++) {
  const j = items[i].json;
  if (!j.cls.ok || !items[i].binary || !items[i].binary.data) continue;
  const isEnfen = j.group === 'enfen' || /^enfen-comunicados/.test(j.id);
  if (!isEnfen && !j.follow) continue;
  const text = utf8Decode(new Uint8Array(await this.helpers.getBinaryDataBuffer(i, 'data')));
  if (isEnfen) pages.push({ url: j.url, text });
  if (j.follow && j.follow.pattern) {
    let rx;
    try { rx = new RegExp(j.follow.pattern, 'gi'); } catch (e) { continue; }
    const found = [...new Set((text.match(rx) || []).map((u) => u.replace(/&amp;/g, '&')))].slice(0, Number(j.follow.max) || 8);
    for (const url of found) {
      add({ id: `${j.id}:enlace`, group: j.group, name: `${j.name} (documento enlazado)`, url, expect: /\.pdf\b/i.test(url) ? 'pdf' : 'any' });
    }
  }
}
for (const url of deriveEnfenTargets(pages)) {
  // Desde la API de WordPress llega la página de la entrada (HTML), no el PDF.
  const pdf = /\.pdf(?:[?#]|$)|wpdmdl=/i.test(url);
  add({ id: 'enfen-pdf', group: 'enfen', name: `Comunicado oficial del ENFEN (${pdf ? 'PDF' : 'página'})`, url, expect: pdf ? 'pdf' : 'any' });
}
return out;

// Generado por n8n/build.mjs desde n8n/nodes/analizar.js y n8n/lib/. No editar en n8n.
// Clasifica una respuesta HTTP: ¿sirve?, ¿qué formato tiene?, y si no
// sirve, ¿por qué? (bloqueo, verificación anti-robots, caída, DNS…).
//
// La misma función corre en el nodo Code de n8n y en tools/probe (Node), de
// modo que la validación desde n8n (AWS), desde GitHub Actions y desde el
// contenedor de desarrollo usan exactamente el mismo criterio. Un bloqueo se
// informa como bloqueo, nunca como «sin datos».

/** Firmas de páginas de bloqueo o verificación. Se buscan en minúsculas en
 * los primeros 64 KB del cuerpo y en las cabeceras. */
const BLOCK_SIGNATURES = [
  { block: 'cloudflare-challenge', body: ['just a moment...', 'cf-chl-', 'challenge-platform', '/cdn-cgi/challenge'], header: { 'cf-mitigated': 'challenge' } },
  { block: 'cloudflare-block', body: ['attention required! | cloudflare', 'cf-error-code', 'sorry, you have been blocked', 'error 1020'] },
  { block: 'human-verification', body: ['verificación de seguridad', 'verificacion de seguridad', 'comprobación de seguridad', 'security check', 'verify you are human', 'verifica que eres humano', 'are you a robot', 'checking your browser'] },
  { block: 'captcha', body: ['g-recaptcha', 'grecaptcha', 'h-captcha', 'hcaptcha.com', 'cf-turnstile', 'px-captcha', 'captcha-delivery.com'] },
  { block: 'imperva', body: ['incapsula incident', '_incapsula_resource', 'request unsuccessful. incapsula'], header: { 'x-iinfo': '' } },
  { block: 'akamai', body: ['reference&#32;&#35;', 'you don\'t have permission to access', 'errors.edgesuite.net'] },
  { block: 'sucuri', body: ['sucuri website firewall', 'access denied - sucuri'], header: { 'x-sucuri-id': '' } },
  { block: 'aws-waf', body: ['awswaf', 'aws-waf-token'], header: { 'x-amzn-waf-action': '' } },
  { block: 'f5-asm', body: ['the requested url was rejected. please consult with your administrator', 'your support id is'] },
  { block: 'fortinet', body: ['fortiguard', 'web page blocked', 'fortigate'] },
  { block: 'datadome', body: ['datadome'], header: { 'x-datadome': '' } },
  { block: 'google-consent', body: ['consent.google.com', 'before you continue to google', 'antes de ir a google'] },
  { block: 'geo', body: ['not available in your country', 'no está disponible en tu país', 'no disponible en su país', 'access from your country', 'geo-restricted'] },
];

/** Errores de red (mensajes de axios/Node en n8n, de fetch/undici en Node). */
const ERROR_KINDS = [
  { verdict: 'dns', re: /ENOTFOUND|EAI_AGAIN|getaddrinfo|upstream dial failed|name not resolved|dns/i, transient: false },
  { verdict: 'timeout', re: /timeout|ETIMEDOUT|ECONNABORTED|UND_ERR_(HEADERS|BODY)_TIMEOUT|aborted/i, transient: true },
  { verdict: 'tls', re: /certificate|self[- ]signed|unable to verify|UNABLE_TO_GET_ISSUER|CERT_|wrong version number|SSL routines|handshake failure/i, transient: false },
  { verdict: 'connection', re: /ECONNRESET|ECONNREFUSED|EHOSTUNREACH|ENETUNREACH|EPIPE|socket hang up|other side closed|UND_ERR_SOCKET|network|fetch failed/i, transient: true },
];

const SCAN_BYTES = 65536;

// El nodo Code de n8n 1.x no tiene TextEncoder ni TextDecoder, y su Buffer
// rechaza los ArrayBuffer creados dentro del nodo: se decodifica a mano.
function utf8Decode(bytes) {
  if (typeof TextDecoder !== 'undefined') return new TextDecoder('utf-8').decode(bytes);
  let out = '';
  const parts = [];
  for (let i = 0; i < bytes.length;) {
    const b = bytes[i];
    let cp = 0xfffd, n = 1;
    if (b < 0x80) { cp = b; }
    else if (b >= 0xc2 && b < 0xe0 && i + 1 < bytes.length && (bytes[i + 1] & 0xc0) === 0x80) { cp = ((b & 0x1f) << 6) | (bytes[i + 1] & 0x3f); n = 2; }
    else if (b >= 0xe0 && b < 0xf0 && i + 2 < bytes.length && (bytes[i + 1] & 0xc0) === 0x80 && (bytes[i + 2] & 0xc0) === 0x80) { cp = ((b & 0x0f) << 12) | ((bytes[i + 1] & 0x3f) << 6) | (bytes[i + 2] & 0x3f); n = 3; }
    else if (b >= 0xf0 && b < 0xf5 && i + 3 < bytes.length && (bytes[i + 1] & 0xc0) === 0x80 && (bytes[i + 2] & 0xc0) === 0x80 && (bytes[i + 3] & 0xc0) === 0x80) { cp = ((b & 0x07) << 18) | ((bytes[i + 1] & 0x3f) << 12) | ((bytes[i + 2] & 0x3f) << 6) | (bytes[i + 3] & 0x3f); n = 4; }
    parts.push(cp);
    i += n;
    if (parts.length >= 8192) { out += String.fromCodePoint.apply(null, parts); parts.length = 0; }
  }
  return out + String.fromCodePoint.apply(null, parts);
}

function utf8Encode(text) {
  if (typeof TextEncoder !== 'undefined') return new TextEncoder().encode(text);
  const out = [];
  for (const ch of text) {
    const cp = ch.codePointAt(0);
    if (cp < 0x80) out.push(cp);
    else if (cp < 0x800) out.push(0xc0 | (cp >> 6), 0x80 | (cp & 63));
    else if (cp < 0x10000) out.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 63), 0x80 | (cp & 63));
    else out.push(0xf0 | (cp >> 18), 0x80 | ((cp >> 12) & 63), 0x80 | ((cp >> 6) & 63), 0x80 | (cp & 63));
  }
  return new Uint8Array(out);
}

function toBytes(body) {
  if (body == null) return new Uint8Array(0);
  if (body instanceof Uint8Array) return body;
  if (typeof body === 'string') return utf8Encode(body);
  if (body.buffer instanceof ArrayBuffer) return new Uint8Array(body.buffer, body.byteOffset || 0, body.byteLength);
  return new Uint8Array(body);
}

function latin1(bytes, n) {
  const end = Math.min(bytes.length, n);
  let s = '';
  for (let i = 0; i < end; i += 8192) s += String.fromCharCode.apply(null, bytes.subarray(i, Math.min(end, i + 8192)));
  return s;
}

function lowerHeaders(headers) {
  const out = {};
  for (const [k, v] of Object.entries(headers || {})) out[String(k).toLowerCase()] = Array.isArray(v) ? v.join(', ') : String(v);
  return out;
}

/** Detecta el formato real del cuerpo, sin fiarse del Content-Type. */
function detectFormat(bytes, contentType) {
  if (!bytes.length) return 'empty';
  if (bytes[0] === 0x25 && bytes[1] === 0x50 && bytes[2] === 0x44 && bytes[3] === 0x46) return 'pdf';
  let head = latin1(bytes, 4096);
  if (head.charCodeAt(0) === 0xef && head.charCodeAt(1) === 0xbb && head.charCodeAt(2) === 0xbf) head = head.slice(3);
  head = head.replace(/^[\s\u0000]+/, '');
  const low = head.toLowerCase();
  if (low.startsWith('{') || low.startsWith('[')) {
    if (/"version"\s*:\s*"https:\/\/jsonfeed\.org/.test(low)) return 'jsonfeed';
    return 'json';
  }
  if (/<rss[\s>]/.test(low)) return 'rss';
  if (/<feed[\s>]/.test(low) && /xmlns="http:\/\/www\.w3\.org\/2005\/atom"/.test(low)) return 'atom';
  if (/<rdf:rdf[\s>]/.test(low)) return 'rdf';
  if (/<feed[\s>]/.test(low)) return 'atom';
  if (/<!doctype html|<html[\s>]|<head[\s>]|<body[\s>]/.test(low)) return 'html';
  if (low.startsWith('<?xml') || low.startsWith('<')) return /<html/.test(low) ? 'html' : 'xml';
  const ct = (contentType || '').toLowerCase();
  if (ct.includes('html')) return 'html';
  // Binario si hay muchos bytes de control en el inicio.
  let ctrl = 0;
  const n = Math.min(bytes.length, 2048);
  for (let i = 0; i < n; i++) { const b = bytes[i]; if (b < 9 || (b > 13 && b < 32)) ctrl++; }
  return ctrl > n * 0.05 ? 'binary' : 'text';
}

const FEED_FORMATS = ['rss', 'atom', 'rdf', 'jsonfeed'];

/** Cuenta entradas y la fecha más reciente de un feed (sin un lector XML
 * completo; el lector tolerante del pipeline es quien decide al final). */
function feedStats(text, format) {
  if (format === 'jsonfeed') {
    try {
      const j = JSON.parse(text);
      const items = Array.isArray(j.items) ? j.items : [];
      return { items: items.length, newest: newestDate(items.map((i) => i.date_published || i.date_modified)), title: String(j.title || '').slice(0, 120) };
    } catch (e) { return { items: 0, newest: null, title: '', parse_error: 'JSON Feed inválido' }; }
  }
  const items = (text.match(/<(item|entry)[\s>]/gi) || []).length;
  const dates = [];
  const re = /<(pubDate|updated|published|dc:date|lastBuildDate)[^>]*>([^<]{6,64})</gi;
  let m;
  while ((m = re.exec(text)) && dates.length < 500) dates.push(m[2].trim());
  const t = /<title[^>]*>(?:<!\[CDATA\[)?([^<\]]{1,200})/i.exec(text);
  return { items, newest: newestDate(dates), title: t ? t[1].trim().slice(0, 120) : '' };
}

function newestDate(values) {
  let best = null;
  for (const v of values) {
    if (!v) continue;
    const t = Date.parse(v);
    if (!Number.isNaN(t) && (best === null || t > best)) best = t;
  }
  return best === null ? null : new Date(best).toISOString();
}

function findBlock(scanLow, headers) {
  for (const sig of BLOCK_SIGNATURES) {
    for (const [h, v] of Object.entries(sig.header || {})) {
      if (h in headers && (!v || headers[h].toLowerCase().includes(v))) return sig.block;
    }
    for (const s of sig.body || []) if (scanLow.includes(s)) return sig.block;
  }
  return null;
}

/**
 * @param {object} r
 * @param {string} r.url
 * @param {string} [r.expect]  feed | html | pdf | json | text | any
 * @param {number|null} [r.status]
 * @param {object} [r.headers]
 * @param {Uint8Array|Buffer|string|null} [r.body]
 * @param {string|null} [r.error]  mensaje de error de red, si no hubo respuesta
 */
function classify(r) {
  const c = classifyRaw(r);
  c.reach = reachClass(c);
  return c;
}

function classifyRaw(r) {
  const headers = lowerHeaders(r.headers);
  const bytes = toBytes(r.body);
  const contentType = headers['content-type'] || '';
  const out = {
    ok: false, verdict: '', block: null, transient: false,
    status: r.status == null ? null : Number(r.status), bytes: bytes.length,
    content_type: contentType.slice(0, 120), detected: 'empty', items: null, newest: null, title: '', note: '',
  };
  const err = r.error ? String(r.error) : '';
  // Proxies de salida devuelven 502 con «upstream dial failed» cuando el nombre no resuelve.
  if (err || (out.status === 502 && /upstream dial failed/i.test(latin1(bytes, 200)))) {
    const msg = err || latin1(bytes, 200);
    const kind = ERROR_KINDS.find((k) => k.re.test(msg));
    out.verdict = kind ? kind.verdict : 'connection';
    out.transient = kind ? kind.transient : true;
    out.status = err ? null : out.status;
    out.note = msg.replace(/\s+/g, ' ').slice(0, 200);
    return out;
  }
  out.detected = detectFormat(bytes, contentType);
  const scan = latin1(bytes, SCAN_BYTES);
  // Las firmas con tildes se buscan en UTF-8 y en Latin-1.
  const scanLow = `${scan}\n${utf8Decode(bytes.subarray(0, SCAN_BYTES))}`.toLowerCase();
  const block = findBlock(scanLow, headers);
  const st = out.status;

  if (st === 429) { out.verdict = 'blocked'; out.block = 'rate-limit'; out.transient = true; return out; }
  if (st === 401 || st === 407) { out.verdict = 'blocked'; out.block = 'auth-required'; return out; }
  if (st === 403 || st === 451) { out.verdict = 'blocked'; out.block = block || (st === 451 ? 'legal' : 'http-403'); return out; }
  if (st === 404 || st === 410) { out.verdict = 'not_found'; return out; }
  if (st !== null && st >= 500) {
    out.verdict = block ? 'blocked' : 'server_error';
    out.block = block;
    out.transient = !block;
    return out;
  }
  if (st === 202 && (block || !bytes.length || out.detected === 'html')) {
    // 202 de anti-robots (ReliefWeb, AWS WAF): «aceptado», pero sin el contenido.
    out.verdict = 'blocked';
    out.block = block || 'bot-202';
    return out;
  }
  if (st !== null && (st < 200 || st >= 300)) {
    // 3xx que no se siguió, 1xx, etc.
    out.verdict = block ? 'blocked' : 'http_error';
    out.block = block;
    return out;
  }
  if (!bytes.length) { out.verdict = 'empty'; out.transient = true; return out; }

  // El registro dice «rss» para cualquier feed y «csv» para tablas de texto.
  const expect = ({ rss: 'feed', atom: 'feed', csv: 'text' })[(r.expect || 'any').toLowerCase()] || (r.expect || 'any').toLowerCase();
  const isFeed = FEED_FORMATS.includes(out.detected);
  // Una página de verificación responde 200 con HTML pequeño: es un bloqueo
  // solo si no es lo que se esperaba (un feed o PDF que menciona «captcha» no lo es).
  const unexpectedHtml = out.detected === 'html' && expect !== 'html' && expect !== 'any';
  if (block && (unexpectedHtml || (out.detected === 'html' && bytes.length < 40000))) {
    out.verdict = 'blocked';
    out.block = block;
    return out;
  }
  if (expect === 'feed') {
    if (!isFeed) {
      out.verdict = 'wrong_type';
      out.note = `se esperaba un feed y llegó ${out.detected}`;
      return out;
    }
    const st2 = feedStats(utf8Decode(bytes), out.detected);
    Object.assign(out, { items: st2.items, newest: st2.newest, title: st2.title });
    if (st2.parse_error) { out.verdict = 'parse_error'; out.note = st2.parse_error; return out; }
    if (!st2.items) { out.verdict = 'empty'; out.note = 'feed sin entradas'; return out; }
  } else if (expect === 'pdf') {
    if (out.detected !== 'pdf') { out.verdict = 'wrong_type'; out.note = `se esperaba PDF y llegó ${out.detected}`; return out; }
  } else if (expect === 'json') {
    if (out.detected !== 'json' && out.detected !== 'jsonfeed') { out.verdict = 'wrong_type'; out.note = `se esperaba JSON y llegó ${out.detected}`; return out; }
    try { JSON.parse(utf8Decode(bytes)); } catch (e) { out.verdict = 'parse_error'; out.note = 'JSON inválido'; return out; }
  } else if (expect === 'text') {
    if (out.detected === 'html' || out.detected === 'binary') { out.verdict = 'wrong_type'; out.note = `se esperaba texto y llegó ${out.detected}`; return out; }
  } else if (expect === 'html') {
    // Un bloqueo llega como HTML: si llegó otra cosa, no es un bloqueo y se
    // guarda igual (el registro puede equivocarse de tipo).
    if (out.detected !== 'html' && out.detected !== 'xml') out.note = `llegó ${out.detected}; el registro esperaba HTML`;
    else if (bytes.length < 500) { out.verdict = 'empty'; out.note = 'HTML casi vacío'; return out; }
  }
  if (out.detected === 'html' || out.detected === 'xml') {
    const t = /<title[^>]*>([^<]{1,200})/i.exec(scan);
    if (t && !out.title) out.title = t[1].trim().slice(0, 120);
  }
  out.ok = true;
  out.verdict = 'ok';
  return out;
}

/** Clase de alcance del registro (python/enso/reach.py: ok, empty, http-403,
 * http-4xx, http-5xx, timeout, connect, dns, tls, challenge), para que las
 * mediciones desde n8n se comparen con las de Actions y del Perú. */
function reachClass(c) {
  switch (c.verdict) {
    case 'ok': return 'ok';
    case 'timeout': return 'timeout';
    case 'connection': return 'connect';
    case 'dns': return 'dns';
    case 'tls': return 'tls';
    case 'not_found': case 'http_error': return 'http-4xx';
    case 'server_error': return 'http-5xx';
    case 'blocked':
      if (c.block === 'http-403') return 'http-403';
      if (c.block === 'rate-limit' || c.block === 'auth-required' || c.block === 'legal') return 'http-4xx';
      return 'challenge';
    default: return 'empty'; // vacío, tipo inesperado o ilegible: responde, pero sin contenido útil
  }
}

/** Extensión del archivo guardado según el formato detectado. */
function fileExtension(detected) {
  if (detected === 'pdf') return 'pdf';
  if (detected === 'json' || detected === 'jsonfeed') return 'json';
  if (['rss', 'atom', 'rdf', 'xml'].includes(detected)) return 'xml';
  if (detected === 'html') return 'html';
  return 'txt';
}

// ---- nodo ----
// Clasifica cada respuesta del nodo de descarga (mismo criterio que
// tools/probe.mjs) y deja el cuerpo solo en las válidas.
const targets = $('Segunda pasada').all();
const items = $input.all();
const now = new Date().toISOString().replace(/\.\d{3}Z$/, '+00:00');
const out = [];
for (let i = 0; i < items.length; i++) {
  const it = items[i];
  const pi = Array.isArray(it.pairedItem) ? it.pairedItem[0] : it.pairedItem;
  const idx = typeof pi === 'number' ? pi : (pi && typeof pi.item === 'number' ? pi.item : i);
  const t = (targets[idx] || targets[i] || { json: {} }).json;
  const j = it.json || {};
  let body = null;
  let error = null;
  if (j.error) {
    const e = j.error;
    error = typeof e === 'string' ? e : [e.code, e.message, e.description, e.cause && e.cause.code].filter(Boolean).join(': ') || JSON.stringify(e).slice(0, 300);
  }
  if (!error && it.binary && it.binary.data) {
    try {
      body = new Uint8Array(await this.helpers.getBinaryDataBuffer(i, 'data'));
    } catch (e) {
      body = it.binary.data.data ? new Uint8Array(Buffer.from(it.binary.data.data, 'base64')) : null;
    }
  }
  const status = j.statusCode == null ? null : j.statusCode;
  const cls = classify({ url: t.url, expect: t.expect, status, headers: j.headers || {}, body, error });
  const o = { json: { id: t.id, group: t.group, name: t.name, url: t.url, expect: t.expect, pass: t.pass || 1, fetched_at: now, cls }, pairedItem: { item: i } };
  if (cls.ok && it.binary && it.binary.data) o.binary = { data: it.binary.data };
  out.push(o);
}
return out;

// Generado por n8n/build.mjs desde n8n/nodes/preparar.js y n8n/lib/. No editar en n8n.
// SHA-256 y SHA-1 en JavaScript puro. El nodo Code de n8n no permite
// require('crypto') salvo que el administrador lo habilite
// (NODE_FUNCTION_ALLOW_BUILTIN), así que no dependemos de él.

function sha256Hex(bytes) {
  const K = new Uint32Array([
    0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
    0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
    0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
    0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
    0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
    0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
    0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
    0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
  ]);
  const H = new Uint32Array([0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19]);
  const W = new Uint32Array(64);
  const blocks = padMessage(bytes, false);
  for (let off = 0; off < blocks.length; off += 64) {
    for (let t = 0; t < 16; t++) {
      const j = off + t * 4;
      W[t] = (blocks[j] << 24) | (blocks[j + 1] << 16) | (blocks[j + 2] << 8) | blocks[j + 3];
    }
    for (let t = 16; t < 64; t++) {
      const a = W[t - 15], b = W[t - 2];
      const s0 = ((a >>> 7) | (a << 25)) ^ ((a >>> 18) | (a << 14)) ^ (a >>> 3);
      const s1 = ((b >>> 17) | (b << 15)) ^ ((b >>> 19) | (b << 13)) ^ (b >>> 10);
      W[t] = (W[t - 16] + s0 + W[t - 7] + s1) | 0;
    }
    let a = H[0], b = H[1], c = H[2], d = H[3], e = H[4], f = H[5], g = H[6], h = H[7];
    for (let t = 0; t < 64; t++) {
      const S1 = ((e >>> 6) | (e << 26)) ^ ((e >>> 11) | (e << 21)) ^ ((e >>> 25) | (e << 7));
      const ch = (e & f) ^ (~e & g);
      const t1 = (h + S1 + ch + K[t] + W[t]) | 0;
      const S0 = ((a >>> 2) | (a << 30)) ^ ((a >>> 13) | (a << 19)) ^ ((a >>> 22) | (a << 10));
      const maj = (a & b) ^ (a & c) ^ (b & c);
      const t2 = (S0 + maj) | 0;
      h = g; g = f; f = e; e = (d + t1) | 0; d = c; c = b; b = a; a = (t1 + t2) | 0;
    }
    H[0] += a; H[1] += b; H[2] += c; H[3] += d; H[4] += e; H[5] += f; H[6] += g; H[7] += h;
  }
  return wordsHex(H);
}

function sha1Hex(bytes) {
  const H = new Uint32Array([0x67452301, 0xefcdab89, 0x98badcfe, 0x10325476, 0xc3d2e1f0]);
  const W = new Uint32Array(80);
  const blocks = padMessage(bytes, false);
  for (let off = 0; off < blocks.length; off += 64) {
    for (let t = 0; t < 16; t++) {
      const j = off + t * 4;
      W[t] = (blocks[j] << 24) | (blocks[j + 1] << 16) | (blocks[j + 2] << 8) | blocks[j + 3];
    }
    for (let t = 16; t < 80; t++) {
      const x = W[t - 3] ^ W[t - 8] ^ W[t - 14] ^ W[t - 16];
      W[t] = (x << 1) | (x >>> 31);
    }
    let a = H[0], b = H[1], c = H[2], d = H[3], e = H[4];
    for (let t = 0; t < 80; t++) {
      let f, k;
      if (t < 20) { f = (b & c) | (~b & d); k = 0x5a827999; }
      else if (t < 40) { f = b ^ c ^ d; k = 0x6ed9eba1; }
      else if (t < 60) { f = (b & c) | (b & d) | (c & d); k = 0x8f1bbcdc; }
      else { f = b ^ c ^ d; k = 0xca62c1d6; }
      const tmp = (((a << 5) | (a >>> 27)) + f + e + k + W[t]) | 0;
      e = d; d = c; c = (b << 30) | (b >>> 2); b = a; a = tmp;
    }
    H[0] += a; H[1] += b; H[2] += c; H[3] += d; H[4] += e;
  }
  return wordsHex(H);
}

function padMessage(bytes) {
  const len = bytes.length;
  const total = Math.ceil((len + 9) / 64) * 64;
  const out = new Uint8Array(total);
  out.set(bytes);
  out[len] = 0x80;
  // Longitud en bits, big-endian, 64 bits (alcanza con 53 bits de precisión).
  const bits = len * 8;
  const hi = Math.floor(bits / 0x100000000), lo = bits >>> 0;
  out[total - 8] = hi >>> 24; out[total - 7] = (hi >>> 16) & 255; out[total - 6] = (hi >>> 8) & 255; out[total - 5] = hi & 255;
  out[total - 4] = lo >>> 24; out[total - 3] = (lo >>> 16) & 255; out[total - 2] = (lo >>> 8) & 255; out[total - 1] = lo & 255;
  return out;
}

function wordsHex(words) {
  let s = '';
  for (const w of words) s += (w >>> 0).toString(16).padStart(8, '0');
  return s;
}

/** SHA de objeto blob de git: sha1("blob <n>\0" + contenido). Es el que GitHub devuelve al crear el blob. */
function gitBlobSha(bytes) {
  const text = `blob ${bytes.length}\0`; // ASCII: sin TextEncoder (n8n 1.x no lo tiene)
  const head = new Uint8Array(text.length);
  for (let i = 0; i < text.length; i++) head[i] = text.charCodeAt(i);
  const all = new Uint8Array(head.length + bytes.length);
  all.set(head);
  all.set(bytes, head.length);
  return sha1Hex(all);
}

const B64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';

/** Base64 sin Buffer (el Buffer del nodo Code de n8n 1.x falla con datos creados dentro del nodo). */
function toBase64(bytes) {
  const parts = [];
  let chunk = '';
  for (let i = 0; i < bytes.length; i += 3) {
    const a = bytes[i], b = bytes[i + 1], c = bytes[i + 2];
    const n = (a << 16) | ((b || 0) << 8) | (c || 0);
    chunk += B64[n >> 18] + B64[(n >> 12) & 63] + (i + 1 < bytes.length ? B64[(n >> 6) & 63] : '=') + (i + 2 < bytes.length ? B64[n & 63] : '=');
    if (chunk.length >= 65536) { parts.push(chunk); chunk = ''; }
  }
  parts.push(chunk);
  return parts.join('');
}

// Clasifica una respuesta HTTP: ¿sirve?, ¿qué formato tiene?, y si no
// sirve, ¿por qué? (bloqueo, verificación anti-robots, caída, DNS…).
//
// La misma función corre en el nodo Code de n8n y en tools/probe (Node), de
// modo que la validación desde n8n (AWS), desde GitHub Actions y desde el
// contenedor de desarrollo usan exactamente el mismo criterio. Un bloqueo se
// informa como bloqueo, nunca como «sin datos».

/** Firmas de páginas de bloqueo o verificación. Se buscan en minúsculas en
 * los primeros 64 KB del cuerpo y en las cabeceras. */
const BLOCK_SIGNATURES = [
  { block: 'cloudflare-challenge', body: ['just a moment...', 'cf-chl-', 'challenge-platform', '/cdn-cgi/challenge'], header: { 'cf-mitigated': 'challenge' } },
  { block: 'cloudflare-block', body: ['attention required! | cloudflare', 'cf-error-code', 'sorry, you have been blocked', 'error 1020'] },
  { block: 'human-verification', body: ['verificación de seguridad', 'verificacion de seguridad', 'comprobación de seguridad', 'security check', 'verify you are human', 'verifica que eres humano', 'are you a robot', 'checking your browser'] },
  { block: 'captcha', body: ['g-recaptcha', 'grecaptcha', 'h-captcha', 'hcaptcha.com', 'cf-turnstile', 'px-captcha', 'captcha-delivery.com'] },
  { block: 'imperva', body: ['incapsula incident', '_incapsula_resource', 'request unsuccessful. incapsula'], header: { 'x-iinfo': '' } },
  { block: 'akamai', body: ['reference&#32;&#35;', 'you don\'t have permission to access', 'errors.edgesuite.net'] },
  { block: 'sucuri', body: ['sucuri website firewall', 'access denied - sucuri'], header: { 'x-sucuri-id': '' } },
  { block: 'aws-waf', body: ['awswaf', 'aws-waf-token'], header: { 'x-amzn-waf-action': '' } },
  { block: 'f5-asm', body: ['the requested url was rejected. please consult with your administrator', 'your support id is'] },
  { block: 'fortinet', body: ['fortiguard', 'web page blocked', 'fortigate'] },
  { block: 'datadome', body: ['datadome'], header: { 'x-datadome': '' } },
  { block: 'google-consent', body: ['consent.google.com', 'before you continue to google', 'antes de ir a google'] },
  { block: 'geo', body: ['not available in your country', 'no está disponible en tu país', 'no disponible en su país', 'access from your country', 'geo-restricted'] },
];

/** Errores de red (mensajes de axios/Node en n8n, de fetch/undici en Node). */
const ERROR_KINDS = [
  { verdict: 'dns', re: /ENOTFOUND|EAI_AGAIN|getaddrinfo|upstream dial failed|name not resolved|dns/i, transient: false },
  { verdict: 'timeout', re: /timeout|ETIMEDOUT|ECONNABORTED|UND_ERR_(HEADERS|BODY)_TIMEOUT|aborted/i, transient: true },
  { verdict: 'tls', re: /certificate|self[- ]signed|unable to verify|UNABLE_TO_GET_ISSUER|CERT_|wrong version number|SSL routines|handshake failure/i, transient: false },
  { verdict: 'connection', re: /ECONNRESET|ECONNREFUSED|EHOSTUNREACH|ENETUNREACH|EPIPE|socket hang up|other side closed|UND_ERR_SOCKET|network|fetch failed/i, transient: true },
];

const SCAN_BYTES = 65536;

// El nodo Code de n8n 1.x no tiene TextEncoder ni TextDecoder, y su Buffer
// rechaza los ArrayBuffer creados dentro del nodo: se decodifica a mano.
function utf8Decode(bytes) {
  if (typeof TextDecoder !== 'undefined') return new TextDecoder('utf-8').decode(bytes);
  let out = '';
  const parts = [];
  for (let i = 0; i < bytes.length;) {
    const b = bytes[i];
    let cp = 0xfffd, n = 1;
    if (b < 0x80) { cp = b; }
    else if (b >= 0xc2 && b < 0xe0 && i + 1 < bytes.length && (bytes[i + 1] & 0xc0) === 0x80) { cp = ((b & 0x1f) << 6) | (bytes[i + 1] & 0x3f); n = 2; }
    else if (b >= 0xe0 && b < 0xf0 && i + 2 < bytes.length && (bytes[i + 1] & 0xc0) === 0x80 && (bytes[i + 2] & 0xc0) === 0x80) { cp = ((b & 0x0f) << 12) | ((bytes[i + 1] & 0x3f) << 6) | (bytes[i + 2] & 0x3f); n = 3; }
    else if (b >= 0xf0 && b < 0xf5 && i + 3 < bytes.length && (bytes[i + 1] & 0xc0) === 0x80 && (bytes[i + 2] & 0xc0) === 0x80 && (bytes[i + 3] & 0xc0) === 0x80) { cp = ((b & 0x07) << 18) | ((bytes[i + 1] & 0x3f) << 12) | ((bytes[i + 2] & 0x3f) << 6) | (bytes[i + 3] & 0x3f); n = 4; }
    parts.push(cp);
    i += n;
    if (parts.length >= 8192) { out += String.fromCodePoint.apply(null, parts); parts.length = 0; }
  }
  return out + String.fromCodePoint.apply(null, parts);
}

function utf8Encode(text) {
  if (typeof TextEncoder !== 'undefined') return new TextEncoder().encode(text);
  const out = [];
  for (const ch of text) {
    const cp = ch.codePointAt(0);
    if (cp < 0x80) out.push(cp);
    else if (cp < 0x800) out.push(0xc0 | (cp >> 6), 0x80 | (cp & 63));
    else if (cp < 0x10000) out.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 63), 0x80 | (cp & 63));
    else out.push(0xf0 | (cp >> 18), 0x80 | ((cp >> 12) & 63), 0x80 | ((cp >> 6) & 63), 0x80 | (cp & 63));
  }
  return new Uint8Array(out);
}

function toBytes(body) {
  if (body == null) return new Uint8Array(0);
  if (body instanceof Uint8Array) return body;
  if (typeof body === 'string') return utf8Encode(body);
  if (body.buffer instanceof ArrayBuffer) return new Uint8Array(body.buffer, body.byteOffset || 0, body.byteLength);
  return new Uint8Array(body);
}

function latin1(bytes, n) {
  const end = Math.min(bytes.length, n);
  let s = '';
  for (let i = 0; i < end; i += 8192) s += String.fromCharCode.apply(null, bytes.subarray(i, Math.min(end, i + 8192)));
  return s;
}

function lowerHeaders(headers) {
  const out = {};
  for (const [k, v] of Object.entries(headers || {})) out[String(k).toLowerCase()] = Array.isArray(v) ? v.join(', ') : String(v);
  return out;
}

/** Detecta el formato real del cuerpo, sin fiarse del Content-Type. */
function detectFormat(bytes, contentType) {
  if (!bytes.length) return 'empty';
  if (bytes[0] === 0x25 && bytes[1] === 0x50 && bytes[2] === 0x44 && bytes[3] === 0x46) return 'pdf';
  let head = latin1(bytes, 4096);
  if (head.charCodeAt(0) === 0xef && head.charCodeAt(1) === 0xbb && head.charCodeAt(2) === 0xbf) head = head.slice(3);
  head = head.replace(/^[\s\u0000]+/, '');
  const low = head.toLowerCase();
  if (low.startsWith('{') || low.startsWith('[')) {
    if (/"version"\s*:\s*"https:\/\/jsonfeed\.org/.test(low)) return 'jsonfeed';
    return 'json';
  }
  if (/<rss[\s>]/.test(low)) return 'rss';
  if (/<feed[\s>]/.test(low) && /xmlns="http:\/\/www\.w3\.org\/2005\/atom"/.test(low)) return 'atom';
  if (/<rdf:rdf[\s>]/.test(low)) return 'rdf';
  if (/<feed[\s>]/.test(low)) return 'atom';
  if (/<!doctype html|<html[\s>]|<head[\s>]|<body[\s>]/.test(low)) return 'html';
  if (low.startsWith('<?xml') || low.startsWith('<')) return /<html/.test(low) ? 'html' : 'xml';
  const ct = (contentType || '').toLowerCase();
  if (ct.includes('html')) return 'html';
  // Binario si hay muchos bytes de control en el inicio.
  let ctrl = 0;
  const n = Math.min(bytes.length, 2048);
  for (let i = 0; i < n; i++) { const b = bytes[i]; if (b < 9 || (b > 13 && b < 32)) ctrl++; }
  return ctrl > n * 0.05 ? 'binary' : 'text';
}

const FEED_FORMATS = ['rss', 'atom', 'rdf', 'jsonfeed'];

/** Cuenta entradas y la fecha más reciente de un feed (sin un lector XML
 * completo; el lector tolerante del pipeline es quien decide al final). */
function feedStats(text, format) {
  if (format === 'jsonfeed') {
    try {
      const j = JSON.parse(text);
      const items = Array.isArray(j.items) ? j.items : [];
      return { items: items.length, newest: newestDate(items.map((i) => i.date_published || i.date_modified)), title: String(j.title || '').slice(0, 120) };
    } catch (e) { return { items: 0, newest: null, title: '', parse_error: 'JSON Feed inválido' }; }
  }
  const items = (text.match(/<(item|entry)[\s>]/gi) || []).length;
  const dates = [];
  const re = /<(pubDate|updated|published|dc:date|lastBuildDate)[^>]*>([^<]{6,64})</gi;
  let m;
  while ((m = re.exec(text)) && dates.length < 500) dates.push(m[2].trim());
  const t = /<title[^>]*>(?:<!\[CDATA\[)?([^<\]]{1,200})/i.exec(text);
  return { items, newest: newestDate(dates), title: t ? t[1].trim().slice(0, 120) : '' };
}

function newestDate(values) {
  let best = null;
  for (const v of values) {
    if (!v) continue;
    const t = Date.parse(v);
    if (!Number.isNaN(t) && (best === null || t > best)) best = t;
  }
  return best === null ? null : new Date(best).toISOString();
}

function findBlock(scanLow, headers) {
  for (const sig of BLOCK_SIGNATURES) {
    for (const [h, v] of Object.entries(sig.header || {})) {
      if (h in headers && (!v || headers[h].toLowerCase().includes(v))) return sig.block;
    }
    for (const s of sig.body || []) if (scanLow.includes(s)) return sig.block;
  }
  return null;
}

/**
 * @param {object} r
 * @param {string} r.url
 * @param {string} [r.expect]  feed | html | pdf | json | text | any
 * @param {number|null} [r.status]
 * @param {object} [r.headers]
 * @param {Uint8Array|Buffer|string|null} [r.body]
 * @param {string|null} [r.error]  mensaje de error de red, si no hubo respuesta
 */
function classify(r) {
  const c = classifyRaw(r);
  c.reach = reachClass(c);
  return c;
}

function classifyRaw(r) {
  const headers = lowerHeaders(r.headers);
  const bytes = toBytes(r.body);
  const contentType = headers['content-type'] || '';
  const out = {
    ok: false, verdict: '', block: null, transient: false,
    status: r.status == null ? null : Number(r.status), bytes: bytes.length,
    content_type: contentType.slice(0, 120), detected: 'empty', items: null, newest: null, title: '', note: '',
  };
  const err = r.error ? String(r.error) : '';
  // Proxies de salida devuelven 502 con «upstream dial failed» cuando el nombre no resuelve.
  if (err || (out.status === 502 && /upstream dial failed/i.test(latin1(bytes, 200)))) {
    const msg = err || latin1(bytes, 200);
    const kind = ERROR_KINDS.find((k) => k.re.test(msg));
    out.verdict = kind ? kind.verdict : 'connection';
    out.transient = kind ? kind.transient : true;
    out.status = err ? null : out.status;
    out.note = msg.replace(/\s+/g, ' ').slice(0, 200);
    return out;
  }
  out.detected = detectFormat(bytes, contentType);
  const scan = latin1(bytes, SCAN_BYTES);
  // Las firmas con tildes se buscan en UTF-8 y en Latin-1.
  const scanLow = `${scan}\n${utf8Decode(bytes.subarray(0, SCAN_BYTES))}`.toLowerCase();
  const block = findBlock(scanLow, headers);
  const st = out.status;

  if (st === 429) { out.verdict = 'blocked'; out.block = 'rate-limit'; out.transient = true; return out; }
  if (st === 401 || st === 407) { out.verdict = 'blocked'; out.block = 'auth-required'; return out; }
  if (st === 403 || st === 451) { out.verdict = 'blocked'; out.block = block || (st === 451 ? 'legal' : 'http-403'); return out; }
  if (st === 404 || st === 410) { out.verdict = 'not_found'; return out; }
  if (st !== null && st >= 500) {
    out.verdict = block ? 'blocked' : 'server_error';
    out.block = block;
    out.transient = !block;
    return out;
  }
  if (st === 202 && (block || !bytes.length || out.detected === 'html')) {
    // 202 de anti-robots (ReliefWeb, AWS WAF): «aceptado», pero sin el contenido.
    out.verdict = 'blocked';
    out.block = block || 'bot-202';
    return out;
  }
  if (st !== null && (st < 200 || st >= 300)) {
    // 3xx que no se siguió, 1xx, etc.
    out.verdict = block ? 'blocked' : 'http_error';
    out.block = block;
    return out;
  }
  if (!bytes.length) { out.verdict = 'empty'; out.transient = true; return out; }

  // El registro dice «rss» para cualquier feed y «csv» para tablas de texto.
  const expect = ({ rss: 'feed', atom: 'feed', csv: 'text' })[(r.expect || 'any').toLowerCase()] || (r.expect || 'any').toLowerCase();
  const isFeed = FEED_FORMATS.includes(out.detected);
  // Una página de verificación responde 200 con HTML pequeño: es un bloqueo
  // solo si no es lo que se esperaba (un feed o PDF que menciona «captcha» no lo es).
  const unexpectedHtml = out.detected === 'html' && expect !== 'html' && expect !== 'any';
  if (block && (unexpectedHtml || (out.detected === 'html' && bytes.length < 40000))) {
    out.verdict = 'blocked';
    out.block = block;
    return out;
  }
  if (expect === 'feed') {
    if (!isFeed) {
      out.verdict = 'wrong_type';
      out.note = `se esperaba un feed y llegó ${out.detected}`;
      return out;
    }
    const st2 = feedStats(utf8Decode(bytes), out.detected);
    Object.assign(out, { items: st2.items, newest: st2.newest, title: st2.title });
    if (st2.parse_error) { out.verdict = 'parse_error'; out.note = st2.parse_error; return out; }
    if (!st2.items) { out.verdict = 'empty'; out.note = 'feed sin entradas'; return out; }
  } else if (expect === 'pdf') {
    if (out.detected !== 'pdf') { out.verdict = 'wrong_type'; out.note = `se esperaba PDF y llegó ${out.detected}`; return out; }
  } else if (expect === 'json') {
    if (out.detected !== 'json' && out.detected !== 'jsonfeed') { out.verdict = 'wrong_type'; out.note = `se esperaba JSON y llegó ${out.detected}`; return out; }
    try { JSON.parse(utf8Decode(bytes)); } catch (e) { out.verdict = 'parse_error'; out.note = 'JSON inválido'; return out; }
  } else if (expect === 'text') {
    if (out.detected === 'html' || out.detected === 'binary') { out.verdict = 'wrong_type'; out.note = `se esperaba texto y llegó ${out.detected}`; return out; }
  } else if (expect === 'html') {
    // Un bloqueo llega como HTML: si llegó otra cosa, no es un bloqueo y se
    // guarda igual (el registro puede equivocarse de tipo).
    if (out.detected !== 'html' && out.detected !== 'xml') out.note = `llegó ${out.detected}; el registro esperaba HTML`;
    else if (bytes.length < 500) { out.verdict = 'empty'; out.note = 'HTML casi vacío'; return out; }
  }
  if (out.detected === 'html' || out.detected === 'xml') {
    const t = /<title[^>]*>([^<]{1,200})/i.exec(scan);
    if (t && !out.title) out.title = t[1].trim().slice(0, 120);
  }
  out.ok = true;
  out.verdict = 'ok';
  return out;
}

/** Clase de alcance del registro (python/enso/reach.py: ok, empty, http-403,
 * http-4xx, http-5xx, timeout, connect, dns, tls, challenge), para que las
 * mediciones desde n8n se comparen con las de Actions y del Perú. */
function reachClass(c) {
  switch (c.verdict) {
    case 'ok': return 'ok';
    case 'timeout': return 'timeout';
    case 'connection': return 'connect';
    case 'dns': return 'dns';
    case 'tls': return 'tls';
    case 'not_found': case 'http_error': return 'http-4xx';
    case 'server_error': return 'http-5xx';
    case 'blocked':
      if (c.block === 'http-403') return 'http-403';
      if (c.block === 'rate-limit' || c.block === 'auth-required' || c.block === 'legal') return 'http-4xx';
      return 'challenge';
    default: return 'empty'; // vacío, tipo inesperado o ilegible: responde, pero sin contenido útil
  }
}

/** Extensión del archivo guardado según el formato detectado. */
function fileExtension(detected) {
  if (detected === 'pdf') return 'pdf';
  if (detected === 'json' || detected === 'jsonfeed') return 'json';
  if (['rss', 'atom', 'rdf', 'xml'].includes(detected)) return 'xml';
  if (detected === 'html') return 'html';
  return 'txt';
}

// Arma la copia que n8n publica en la rama de datos, en el mismo formato
// que el recolector del Perú («enso-relay/1», ver python/enso/fetch.py
// Relay y python/tools/peru_collector.py):
//
//   index.json            lista de URL descargadas con su estado
//   files/<sha16>.<ext>   cuerpo original de cada respuesta válida
//
// Diferencias con el recolector del Perú:
// - Cada entrada lleva la clasificación (ok, bloqueo, tipo de bloqueo…) y el
//   SHA de blob de git, para reutilizar los archivos que no cambiaron sin
//   volver a subirlos.
// - Si una URL falla ahora pero la copia anterior tiene una válida de hace
//   menos de ``carryHours``, se conserva esa copia (``carried: true``) con su
//   fecha original. El pipeline mide la antigüedad por entrada.
// - index.json se publica siempre, aunque todo falle: es el latido que
//   distingue «n8n caído» de «fuentes caídas».

/* global sha256Hex, gitBlobSha, fileExtension */

function entryFrom(r) {
  const c = r.cls || {};
  const e = {
    url: r.url,
    id: r.id,
    group: r.group,
    status: c.status ?? null,
    content_type: c.content_type || '',
    bytes: c.bytes || 0,
    fetched_at: r.fetched_at,
    verdict: c.verdict,
    reach: c.reach,
  };
  if (c.block) e.block = c.block;
  if (c.detected && c.detected !== 'empty') e.detected = c.detected;
  if (c.items != null) e.items = c.items;
  if (c.newest) e.newest = c.newest;
  if (c.note) e.note = c.note;
  if (r.pass && r.pass > 1) e.pass = r.pass;
  if (r.aliases && r.aliases.length) e.aliases = r.aliases;
  return e;
}

/** Elige un resultado por URL: el válido si lo hay, si no el último intento. */
function pickResults(results) {
  const byUrl = new Map();
  for (const r of results) {
    const prev = byUrl.get(r.url);
    if (!prev || (!prev.cls?.ok && (r.cls?.ok || (r.pass || 1) >= (prev.pass || 1)))) byUrl.set(r.url, r);
  }
  return [...byUrl.values()];
}

function hoursBetween(a, b) {
  const t = Date.parse(a);
  return Number.isNaN(t) ? Infinity : (b.getTime() - t) / 3600000;
}

/**
 * @param {object} p
 * @param {Array} p.results   [{id, url, group, fetched_at, pass, cls, body: Uint8Array|null}]
 * @param {object|null} p.previous  index.json anterior (o null)
 * @param {Date} p.now
 * @param {object} p.collector  datos del recolector para index.json
 * @param {number} [p.carryHours]
 * @param {number} [p.maxBytes]
 * @returns {{index: object, files: Array<{path: string, git_blob: string, sha256: string, body: Uint8Array|null}>}}
 */
function buildSnapshot({ results, previous, now, collector, carryHours = 72, maxBytes = 8000000 }) {
  const prevByUrl = new Map();
  for (const e of (previous && previous.entries) || []) {
    if (e.status === 200 && e.file && e.git_blob && e.sha256) prevByUrl.set(e.url, e);
  }
  const files = new Map();
  const entries = [];
  for (const r of pickResults(results)) {
    const e = entryFrom(r);
    const body = r.body;
    if (r.cls && r.cls.ok && body && body.length) {
      if (body.length > maxBytes) {
        e.note = `${e.note ? e.note + '; ' : ''}más de ${maxBytes} bytes: no se guarda`;
      } else {
        const sha = sha256Hex(body);
        const path = `files/${sha.slice(0, 16)}.${fileExtension(r.cls.detected)}`;
        const prev = [...prevByUrl.values()].find((p) => p.sha256 === sha && p.file === path);
        const blob = prev ? prev.git_blob : gitBlobSha(body);
        if (!files.has(path)) files.set(path, { path, sha256: sha, git_blob: blob, body: prev ? null : body });
        Object.assign(e, { file: path, sha256: sha, git_blob: blob });
      }
    } else {
      const prev = prevByUrl.get(r.url);
      if (prev && hoursBetween(prev.fetched_at, now) <= carryHours) {
        const carried = { ...prev, carried: true, last_attempt: { at: r.fetched_at, verdict: e.verdict, status: e.status } };
        if (e.block) carried.last_attempt.block = e.block;
        if (e.note) carried.last_attempt.note = e.note;
        entries.push(carried);
        if (!files.has(prev.file)) files.set(prev.file, { path: prev.file, sha256: prev.sha256, git_blob: prev.git_blob, body: null });
        continue;
      }
    }
    entries.push(e);
  }
  const groups = [...new Set(entries.map((e) => e.group))];
  const summary = {};
  for (const g of groups) {
    const es = entries.filter((e) => e.group === g);
    summary[g] = `${es.filter((e) => e.verdict === 'ok' && !e.carried).length}/${es.length}`;
  }
  const verdicts = {};
  for (const e of entries) {
    const v = e.carried ? 'carried' : e.verdict;
    verdicts[v] = (verdicts[v] || 0) + 1;
  }
  const index = {
    schema: 'enso-relay/1',
    collected_at: now.toISOString().replace(/\.\d{3}Z$/, '+00:00'),
    collector,
    entries,
    summary,
    verdicts,
  };
  return { index, files: [...files.values()] };
}

/** Latido de la corrida, en el formato del recolector del Perú
 * («enso-relay-heartbeat/1»): ``result`` es «ok» si alguna fuente respondió
 * en esta corrida y «sin-fuentes» si ninguna (n8n funciona, las fuentes no). */
function heartbeat(index, now) {
  const fresh = index.entries.filter((e) => e.verdict === 'ok' && !e.carried);
  return {
    schema: 'enso-relay-heartbeat/1',
    at: now.toISOString().replace(/\.\d{3}Z$/, '+00:00'),
    result: fresh.length ? 'ok' : 'sin-fuentes',
    reachable: `${fresh.length}/${index.entries.length}`,
    summary: index.summary,
    failures: index.entries.filter((e) => e.verdict !== 'ok' || e.carried).slice(0, 40).map((e) => {
      const f = { url: e.url, status: e.carried ? e.last_attempt.status : e.status, verdict: e.carried ? e.last_attempt.verdict : e.verdict };
      const block = e.carried ? e.last_attempt.block : e.block;
      if (block) f.block = block;
      return f;
    }),
    collector: index.collector,
  };
}

// ---- nodo ----
// Arma la copia (index.json + files/) y devuelve un elemento por archivo
// nuevo que hay que subir a GitHub, más index.json, que va siempre (es el
// latido del recolector). Los archivos que no cambiaron reutilizan el blob
// de la copia anterior y no se vuelven a subir.
const cfg = $('Configuración').first().json;
const items = $input.all();
let previous = null;
let previousNote = 'sin copia anterior';
const prevResp = $('Leer copia anterior').first().json;
// Con «Response Format: Text» n8n deja el cuerpo en «data» (en algunas versiones, en «body»).
const prevBody = prevResp.data !== undefined ? prevResp.data : prevResp.body;
if (prevResp.statusCode === 200 && prevBody) {
  try {
    const j = typeof prevBody === 'string' ? JSON.parse(prevBody) : prevBody;
    if (j.schema === 'enso-relay/1') { previous = j; previousNote = `copia anterior del ${j.collected_at}`; }
  } catch (e) { previousNote = 'index.json anterior ilegible'; }
