// Generado por n8n/build.mjs desde n8n/nodes/arbol.js. No editar en n8n.
// Comprueba que GitHub guardó cada blob con el SHA calculado aquí y arma el
// árbol completo de la copia (los archivos reutilizados y los nuevos).
const sent = $('Preparar copia').all();
const got = $input.all();
if (got.length !== sent.length) throw new Error(`GitHub devolvió ${got.length} blobs para ${sent.length} archivos`);
for (let i = 0; i < sent.length; i++) {
  const want = sent[i].json.git_blob;
  const have = got[i].json.sha;
  if (want !== have) throw new Error(`blob de ${sent[i].json.path}: GitHub devolvió ${have}, se esperaba ${want}`);
}
const last = sent[sent.length - 1].json;
const tree = last.manifest.map((f) => ({ path: f.path, mode: '100644', type: 'blob', sha: f.git_blob }));
const groups = Object.entries(last.summary || {}).map(([g, v]) => `${g} ${v}`).join(', ');
const message = `relay n8n: ${last.collected_at} (${groups || 'sin fuentes'})`;
return [{ json: { tree, message, summary: last.summary, verdicts: last.verdicts, collected_at: last.collected_at, uploaded: sent.length, reused: last.reused } }];

// Generado por n8n/build.mjs desde n8n/nodes/commit.js. No editar en n8n.
// Cuerpo del commit: el árbol recién creado, sin padre. La rama guarda solo
// la última copia (el historial no crece con cada corrida); el pipeline
// archiva lo que usa en la rama data-archive.
const info = $('Armar árbol').first().json;
return [{ json: { message: info.message, tree: $input.first().json.sha, parents: [] } }];

// Generado por n8n/build.mjs desde n8n/nodes/rama.js. No editar en n8n.
// Mueve la rama de datos al commit nuevo: la crea si no existe y si existe
// la reemplaza (force, porque el commit no tiene padre). Las expresiones de
// los parámetros JSON no pueden usar $('Nodo') en n8n 1.x: se arma aquí.
const cfg = $('Configuración').first().json;
const commit = $('Crear commit').first().json.sha;
const exists = $input.first().json.statusCode === 200;
const base = `${cfg.api}/repos/${cfg.repo}/git/refs`;
return [{ json: exists
  ? { method: 'PATCH', url: `${base}/heads/${cfg.data_branch}`, body: { sha: commit, force: true }, commit }
  : { method: 'POST', url: base, body: { ref: `refs/heads/${cfg.data_branch}`, sha: commit }, commit } }];

// Generado por n8n/build.mjs desde n8n/nodes/resumen.js. No editar en n8n.
// Resultado de la corrida. Falla (y n8n la marca en rojo) si la copia no
// llegó a GitHub; la falta de fuentes se ve en index.json, no es un error
// del recolector.
const cfg = $('Configuración').first().json;
const r = $input.first().json;
const info = $('Armar árbol').first().json;
const ok = r.statusCode === 200 || r.statusCode === 201;
if (!ok) {
  throw new Error(`No se pudo actualizar ${cfg.repo}@${cfg.data_branch}: HTTP ${r.statusCode} ${JSON.stringify(r.body || r.data || '').slice(0, 300)}`);
}
return [{ json: {
  resultado: `Copia publicada en ${cfg.repo}@${cfg.data_branch}`,
  commit: $('Preparar rama').first().json.commit,
  recolectado: info.collected_at,
  resumen: info.summary,
  veredictos: info.verdicts,
  archivos_subidos: info.uploaded,
  archivos_reutilizados: info.reused,
} }];
